package com.hrcoresystem.hrcore_api.modules.tenant.incidents.infrastructure.persistence;
import com.hrcoresystem.hrcore_api.modules.tenant.incidents.domain.model.IncidentModels.AttachmentType; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="incident_attachments") @Getter @Setter public class IncidentAttachmentEntity { @Id private UUID id; @Column(name="incident_id",nullable=false) private UUID incidentId; @Enumerated(EnumType.STRING) @Column(name="attachment_type",nullable=false) private AttachmentType attachmentType; @Column(nullable=false) private String filename; @Column(name="storage_key",nullable=false) private String storageKey; @Column(name="mime_type",nullable=false) private String mimeType; @Column(name="file_size",nullable=false) private long fileSize; @Column(columnDefinition="TEXT") private String description; @Column(name="uploaded_by") private UUID uploadedBy; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @PrePersist void created(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();} }
